<template>
  <div class="page">
    <div class="activity-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>营销活动</h3>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="name" label="活动名称" min-width="200" />
            <el-table-column prop="type" label="活动类型" min-width="120" />
            <el-table-column prop="starttime" label="开始时间" min-width="180" />
            <el-table-column prop="endtime" label="结束时间" min-width="180" />
            <el-table-column prop="participants" label="参与人数" min-width="110" />
            <el-table-column prop="tag" label="状态" min-width="100">
              <template #default="scope">
                <el-tag :type="tagType(scope.row.tag)" disable-transitions>{{ scope.row.tag }}</el-tag>
              </template>
            </el-table-column>
            <el-table-column label="操作" min-width="110">
              <template #default="scope">
                <el-button
                  size="small"
                  :type="scope.row.tag === '已结束' ? 'success' : 'danger'"
                  @click="handleToggle(scope.row.name)"
                >
                  {{ scope.row.tag === '已结束' ? '开启' : '结束' }}
                </el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="activity-manage__pagination-wrap">
        <div class="totalnum">
          <h3>活动统计</h3>
          <p>当前共 {{ tableData.length }} 个活动</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed } from 'vue'
import { ElMessage } from 'element-plus'

const currentPage = ref(1)
const pageSize = ref(6)

const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

const tagType = (tag) => {
  const map = {
    '进行中': 'success',
    '未开始': 'primary',
    '已结束': 'danger',
  }
  return map[tag] || 'info'
}

const handleToggle = (name) => {
  const row = tableData.value.find((item) => item.name === name)
  if (!row) return
  row.tag = row.tag === '已结束' ? '进行中' : '已结束'
  ElMessage.success(`活动「${name}」已${row.tag === '进行中' ? '开启' : '结束'}`)
}

const tableData = ref([
  {
    name: '新年首单立减',
    type: '满减',
    starttime: '2024-01-01 00:00:00',
    endtime: '2024-02-10 23:59:59',
    participants: 1250,
    tag: '进行中',
  },
  {
    name: '会员积分翻倍',
    type: '积分',
    starttime: '2024-03-01 00:00:00',
    endtime: '2024-03-31 23:59:59',
    participants: 980,
    tag: '进行中',
  },
  {
    name: '新品限时 8 折',
    type: '折扣',
    starttime: '2024-04-15 00:00:00',
    endtime: '2024-05-15 23:59:59',
    participants: 0,
    tag: '未开始',
  },
  {
    name: '双十一狂欢购',
    type: '满减',
    starttime: '2023-11-01 00:00:00',
    endtime: '2023-11-11 23:59:59',
    participants: 3200,
    tag: '已结束',
  },
  {
    name: '周年庆买二送一',
    type: '买赠',
    starttime: '2023-12-20 00:00:00',
    endtime: '2024-01-05 23:59:59',
    participants: 2100,
    tag: '已结束',
  },
  {
    name: '午市专享优惠',
    type: '折扣',
    starttime: '2024-05-01 00:00:00',
    endtime: '2024-06-30 23:59:59',
    participants: 640,
    tag: '进行中',
  },
])
</script>

